const ASSETS={"/index.html":{"type":"text/html; charset=utf-8","body":"<!doctype html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n  <title>拾忆 · 让存下的东西真的回来</title>\n  <meta name=\"description\" content=\"记录保存目的和记忆线索，让截图、链接和念头在合适的时候重新出现。\">\n  <link rel=\"icon\" href=\"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 40 40'%3E%3Crect width='40' height='40' rx='12' fill='%23273531'/%3E%3Cpath d='M12 12h16v16H12z' fill='none' stroke='white' stroke-width='3'/%3E%3C/svg%3E\">\n  <link rel=\"stylesheet\" href=\"/style.css\">\n</head>\n<body>\n  <aside class=\"rail\">\n    <button class=\"logo\" id=\"home\" aria-label=\"回到首页\">拾</button>\n    <nav aria-label=\"主要功能\">\n      <button data-view=\"library\" aria-label=\"全部记忆\"><span class=\"navicon\">▤</span><span>记忆</span></button>\n      <button data-view=\"recall\" aria-label=\"凭线索找回\"><span class=\"navicon\">⌕</span><span>找回</span></button>\n      <button data-view=\"tasks\" aria-label=\"等待处理\"><span class=\"navicon\">◷</span><span>行动</span></button>\n      <button data-view=\"resurface\" aria-label=\"再次出现\"><span class=\"navicon\">◫</span><span>再见</span></button>\n      <button data-view=\"trash\" aria-label=\"回收站\"><span class=\"navicon\">⌫</span><span>回收站</span></button>\n    </nav>\n    <button id=\"account\" class=\"account\" aria-label=\"账号与能力说明\">我</button>\n  </aside>\n\n  <main>\n    <header>\n      <a href=\"/\" class=\"wordmark\">拾忆 <span>SHIYI</span></a>\n      <span class=\"headernote\" id=\"connection\">连接你的空间…</span>\n    </header>\n\n    <section class=\"workspace\">\n      <div class=\"greeting\">\n        <p class=\"eyebrow\">SAVE THE REASON, NOT JUST THE FILE</p>\n        <h1>不只存下来，<br><span>还要记得为什么。</span></h1>\n        <p>截图、链接、声音和一闪而过的念头，都可以留下当时的目的与线索。</p>\n      </div>\n\n      <div class=\"composer\" id=\"composer\">\n        <div class=\"modebar\" role=\"group\" aria-label=\"收集方式\">\n          <button class=\"active\" data-mode=\"text\">文字 / 链接</button>\n          <button data-mode=\"image\">图片 / 截图</button>\n          <button data-mode=\"audio\">声音</button>\n        </div>\n\n        <div id=\"attachmentArea\" hidden>\n          <label class=\"filepick\" id=\"filepick\">\n            <span id=\"filelabel\">选择图片，或拖到这里</span>\n            <input id=\"file\" type=\"file\" accept=\"image/png,image/jpeg,image/webp\" hidden>\n          </label>\n          <div id=\"attachmentPreview\"></div>\n        </div>\n\n        <div id=\"recordArea\" hidden>\n          <button id=\"record\" class=\"record\">● 开始录音</button>\n          <span id=\"recordState\">最长 2 分钟，可先试听再保存</span>\n        </div>\n\n        <textarea id=\"thought\" aria-label=\"内容或补充说明\" placeholder=\"随手写点什么，也可以粘贴链接…\" maxlength=\"20000\"></textarea>\n\n        <div class=\"captureMeta\">\n          <div>\n            <span class=\"metaLabel\">为什么存？</span>\n            <div class=\"intentChips\" id=\"intentChips\" role=\"group\" aria-label=\"保存目的\">\n              <button data-intent=\"想买\">想买</button>\n              <button data-intent=\"想学\">想学</button>\n              <button data-intent=\"想做\">想做</button>\n              <button data-intent=\"想试试\">想试试</button>\n              <button class=\"active\" data-intent=\"留作参考\">留作参考</button>\n              <button data-intent=\"只是好笑\">只是好笑</button>\n            </div>\n          </div>\n          <div class=\"metaGrid\">\n            <label>以后可能用什么词找？<input id=\"clue\" maxlength=\"120\" placeholder=\"例如：直播、歌名、日语口诀\"></label>\n            <label>从哪里看到的？\n              <select id=\"source\"><option value=\"\">未填写</option><option>小红书</option><option>微信</option><option>直播</option><option>游戏</option><option>网页</option><option>相册</option><option>其他</option></select>\n            </label>\n          </div>\n          <div class=\"photoFields\" id=\"photoFields\" hidden>\n            <div class=\"photoPrompt\"><span>风景复刻</span><p>知道地点时先告诉拾忆，不必等待识图也能保存成计划。</p></div>\n            <div class=\"metaGrid\">\n              <label>这是哪里？<input id=\"place\" maxlength=\"100\" placeholder=\"例如：大理洱海西岸\"></label>\n              <label>想怎么复刻？<input id=\"photoPlan\" maxlength=\"240\" placeholder=\"例如：傍晚去，站在栏杆左侧拍同款构图\"></label>\n            </div>\n          </div>\n          <label class=\"revisitLabel\">什么时候希望它再出现？\n            <select id=\"revisit\"><option>不用提醒</option><option>今晚</option><option>三天后</option><option>下周</option><option>一个月后</option></select>\n          </label>\n        </div>\n\n        <div class=\"composerfoot\">\n          <span id=\"savehint\">保存内容，也保存你当时的目的。</span>\n          <button id=\"save\" class=\"primary\">收好</button>\n        </div>\n      </div>\n\n      <p class=\"privacy\">资料按账号隔离保存 · 关键词找回不调用 AI · 照片识别只在主动点击时运行</p>\n\n      <div class=\"featureGrid\" aria-label=\"主要入口\">\n        <button data-focus-capture><span class=\"featureNo\">01</span><strong>快速存下</strong><small>留下内容和目的</small></button>\n        <button data-view=\"recall\"><span class=\"featureNo\">02</span><strong>凭印象找</strong><small>关键词、来源、时间</small></button>\n        <button data-view=\"tasks\"><span class=\"featureNo\">03</span><strong>等我去做</strong><small>把收藏变成行动</small></button>\n        <button data-view=\"resurface\"><span class=\"featureNo\">04</span><strong>再看一眼</strong><small>每次只回来三条</small></button>\n      </div>\n\n      <section class=\"demoSpotlight\">\n        <img src=\"/assets/demo-scenic-recreation.jpg\" alt=\"山间湖泊与观景栏杆的风景照片演示\">\n        <div>\n          <p class=\"eyebrow\">PHOTO RECREATION · 演示数据</p>\n          <h2>一张风景照，也可以变成下一次出发</h2>\n          <p>记录地点、喜欢它的原因和想复刻的构图。以后开启单张识图时，还能补充画面内容与拍摄建议。</p>\n          <div class=\"demoTags\"><span>想做</span><span>旅行</span><span>风景复刻</span></div>\n          <button id=\"openScenicDemo\">查看这张记忆卡</button>\n        </div>\n      </section>\n\n      <div id=\"homeResults\" hidden></div>\n      <div id=\"banner\" role=\"status\"></div>\n    </section>\n\n    <footer><span>不是帮你收藏更多，而是让存下的东西真的回来。</span><button id=\"aboutPhoto\">照片识别怎么工作？</button></footer>\n  </main>\n\n  <dialog id=\"panel\" class=\"panel\">\n    <div class=\"paneltop\"><div><p class=\"eyebrow\">YOUR MEMORY SPACE</p><h2 id=\"paneltitle\">全部记忆</h2></div><button data-close=\"panel\" aria-label=\"关闭侧栏\">×</button></div>\n    <div id=\"panelbody\"></div>\n  </dialog>\n  <dialog id=\"detail\">\n    <div class=\"modalhead\"><h2>这段记忆</h2><button data-close=\"detail\" aria-label=\"关闭详情\">×</button></div>\n    <div id=\"detailbody\"></div>\n  </dialog>\n  <dialog id=\"confirm\">\n    <div class=\"modalhead\"><h2>移到回收站？</h2><button data-close=\"confirm\" aria-label=\"取消删除\">×</button></div>\n    <p>它将不再出现在找回和行动中，你仍然可以从回收站恢复。</p>\n    <div class=\"actions\"><button data-close=\"confirm\">保留</button><button id=\"confirmDelete\" class=\"danger\">移到回收站</button></div>\n  </dialog>\n  <dialog id=\"accountDialog\">\n    <div class=\"modalhead\"><h2>账号与照片识别</h2><button data-close=\"accountDialog\" aria-label=\"关闭说明\">×</button></div>\n    <div id=\"accountbody\"></div>\n  </dialog>\n  <div id=\"toast\" role=\"status\"></div>\n  <script src=\"/app.js\"></script>\n</body>\n</html>\n"},"/style.css":{"type":"text/css; charset=utf-8","body":":root{--ink:#26332f;--muted:#76827d;--line:#e3e9e5;--accent:#315d4b;--accent-soft:#edf4f0;--paper:#fff;--wash:#f7f9f7;--warm:#aa7043;--danger:#a5524b}*{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 -apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}button,input,textarea,select{font:inherit;color:inherit}button{cursor:pointer;border:0;background:transparent;border-radius:9px;padding:8px 12px}button:hover{background:#f0f4f1}button:disabled{opacity:.45;cursor:not-allowed}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible{outline:2px solid #799d8c;outline-offset:3px}a{color:var(--accent)}\n.rail{width:82px;position:fixed;inset:0 auto 0 0;border-right:1px solid var(--line);background:#fbfcfb;display:flex;align-items:center;flex-direction:column;padding:24px 8px;z-index:3}.logo{width:48px;height:48px;border-radius:14px;background:var(--ink);color:#fff;font-size:18px;font-weight:650}.logo:hover{background:var(--accent)}.rail nav{display:grid;gap:16px;margin-top:42px}.rail nav button{width:62px;color:#77837e;padding:7px 4px}.rail nav button:hover{color:var(--accent)}.navicon{display:block;font-size:22px;line-height:1}.rail nav button span:last-child{display:block;font-size:12px;margin-top:7px;letter-spacing:.08em}.account{margin-top:auto;width:38px;height:38px;border:1px solid #d7dfda;border-radius:50%;font-size:13px;padding:4px}\nmain{margin-left:82px;min-height:100vh;display:flex;flex-direction:column}header{height:88px;display:flex;align-items:center;justify-content:space-between;padding:0 5vw}.wordmark{text-decoration:none;color:var(--ink);font-weight:650;font-size:20px;letter-spacing:.18em}.wordmark span{font-size:12px;font-weight:400;letter-spacing:.22em;color:#9ca5a1;margin-left:12px}.headernote{font-size:12px;color:#909a96}.workspace{width:min(980px,calc(100% - 80px));margin:46px auto 84px}.eyebrow{font-size:12px;color:#91a098;letter-spacing:.2em;margin:0 0 18px}.greeting{margin-bottom:34px}.greeting h1{font-size:clamp(34px,4.5vw,54px);font-weight:520;line-height:1.35;letter-spacing:.02em;margin:0}.greeting h1 span{color:#96a19c}.greeting>p:last-child{font-size:15px;color:var(--muted);margin:17px 0 0}\n.composer{border:1px solid #dce5df;border-radius:20px;padding:18px 22px 17px;box-shadow:0 18px 50px rgba(37,70,52,.055);background:#fff}.modebar{display:flex;gap:6px;margin-bottom:14px}.modebar button{font-size:14px;color:#77837d;padding:6px 11px}.modebar button.active{background:var(--accent-soft);color:var(--accent)}textarea{display:block;width:100%;min-height:92px;resize:vertical;border:0;outline:0;line-height:1.8;padding:13px 6px;background:transparent;font-size:16px}textarea::placeholder,input::placeholder{color:#a1aaa5}.filepick{display:block;padding:24px;text-align:center;border:1px dashed #c4d2c9;background:#f9fbfa;cursor:pointer;border-radius:12px;font-size:14px;color:#708078}.filepick:hover{border-color:var(--accent)}#attachmentPreview{margin:12px 0}#attachmentPreview img{max-width:100%;max-height:260px;border-radius:11px;display:block;margin:auto}audio{width:100%;margin-top:10px}#recordArea{display:flex;align-items:center;gap:12px;margin:10px 0}.record{color:#9c4f4f;background:#fbf1f1;font-size:14px}#recordState{font-size:12px;color:#86918c}\n.captureMeta{border-top:1px solid var(--line);padding-top:17px;display:grid;gap:16px}.metaLabel{display:block;font-size:13px;color:#63716b;margin-bottom:9px}.intentChips{display:flex;gap:7px;flex-wrap:wrap}.intentChips button{font-size:13px;padding:6px 11px;background:#f5f7f5;color:#68756f;border:1px solid transparent}.intentChips button.active{background:#e7f1ec;border-color:#bfd3c8;color:#254f3e}.metaGrid,.detailGrid,.recallGrid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.captureMeta label,.recallBox label{font-size:13px;color:#66736d}.captureMeta input,.captureMeta select,.recallBox input,.recallBox select{display:block;width:100%;margin-top:7px;border:1px solid #dfe5e1;border-radius:9px;background:#fff;padding:9px 11px;outline:0;font-size:14px}.photoFields{padding:14px;border-radius:12px;background:#f5f8f6}.photoPrompt{display:flex;align-items:baseline;gap:12px;margin-bottom:11px}.photoPrompt span{font-size:13px;font-weight:650;color:var(--accent)}.photoPrompt p{margin:0;font-size:12px;color:#7d8983}.revisitLabel{max-width:320px}.composerfoot{display:flex;align-items:center;gap:20px;justify-content:space-between;padding-top:15px}.composerfoot>span{color:#84908a;font-size:12px}.primary{background:var(--ink);color:white;padding:9px 20px;border-radius:9px;white-space:nowrap}.primary:hover{background:var(--accent)}.privacy{font-size:12px;color:#89958f;margin:13px 4px 28px}\n.featureGrid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.featureGrid button{display:grid;grid-template-columns:auto 1fr;text-align:left;column-gap:12px;align-items:start;padding:18px;border:1px solid var(--line);border-radius:13px;background:#fff}.featureGrid button:hover{border-color:#b9cbbf;transform:translateY(-1px)}.featureNo{grid-row:1/3;font-size:11px;color:#99a59f;margin-top:4px}.featureGrid strong{font-size:15px;font-weight:560}.featureGrid small{display:block;color:#89958f;font-size:12px;margin-top:3px}.demoSpotlight{margin-top:42px;display:grid;grid-template-columns:minmax(280px,44%) 1fr;border:1px solid var(--line);border-radius:18px;overflow:hidden;background:#fbfcfb}.demoSpotlight>img{width:100%;height:100%;min-height:285px;object-fit:cover}.demoSpotlight>div{padding:32px 34px;align-self:center}.demoSpotlight .eyebrow{margin-bottom:10px}.demoSpotlight h2{font-size:24px;font-weight:530;line-height:1.45;margin:0 0 12px}.demoSpotlight p:not(.eyebrow){font-size:14px;color:#74817b;margin:0}.demoTags,.memoryMeta{display:flex;gap:7px;flex-wrap:wrap;margin:18px 0}.demoTags span,.memoryMeta>span{font-size:12px;background:#edf3ef;color:#547063;padding:3px 8px;border-radius:6px}.demoSpotlight button{padding:8px 0;margin-top:8px;color:var(--accent);font-size:14px}#banner{font-size:12px;color:#8c9792;margin-top:22px}footer{margin-top:auto;padding:24px 5vw;display:flex;justify-content:space-between;font-size:12px;color:#929d98;border-top:1px solid #f0f2f0}footer button{font-size:12px;color:#74857c;padding:0}\ndialog{border:1px solid #e1e7e3;border-radius:16px;width:min(610px,calc(100% - 28px));max-height:90vh;padding:28px;color:var(--ink);box-shadow:0 25px 100px rgba(22,48,36,.18)}dialog::backdrop{background:rgba(31,48,40,.2);backdrop-filter:blur(4px)}.panel{height:100dvh;max-height:100dvh;width:min(590px,100vw);margin:0 0 0 auto;border-radius:0;border-top:0;border-bottom:0;padding:34px}.paneltop,.modalhead{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:25px}.paneltop .eyebrow{margin-bottom:5px}.paneltop h2,.modalhead h2{font-size:23px;font-weight:520;margin:0}.paneltop button,.modalhead button{font-size:24px;line-height:1;padding:7px}.panelIntro{font-size:13px;color:#78857f;background:#f6f8f6;padding:11px 13px;border-radius:9px;margin:0 0 16px}.itemrow{display:flex;align-items:center;gap:12px;padding:17px 0;border-bottom:1px solid var(--line)}.itemicon{width:39px;height:42px;display:grid;place-items:center;background:#f1f5f2;color:#748b7e;font-size:19px;border-radius:9px;flex-shrink:0}.rowopen{text-align:left;flex:1;min-width:0;padding:0}.rowopen strong{font-size:15px;font-weight:530;display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.rowopen p{font-size:12px;color:#849089;margin:5px 0 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.rowopen:hover{background:transparent;color:var(--accent)}.smallbtn{font-size:13px;color:#77877e;padding:6px}.empty{padding:45px 10px;text-align:center;color:#84918a}.empty strong{font-weight:450;font-size:17px}.empty p{font-size:13px}.panelsearch{width:100%;padding:10px 12px;border:1px solid var(--line);border-radius:9px;outline:0;margin-bottom:9px}.filters{display:flex;gap:6px;flex-wrap:wrap;margin:13px 0}.filters button{font-size:13px;color:#7c8882;padding:4px 9px}.filters button.active{background:var(--accent-soft);color:var(--accent)}.muted{color:#7c8983;font-size:14px}.error{color:var(--danger);font-size:14px}.resultCount{font-size:12px;color:#718179;margin:20px 0 0}.recallBox{border:1px solid var(--line);border-radius:13px;padding:16px}.recallBox>label{display:block;margin-bottom:13px}.recallBox input,.recallBox select{font-size:14px}.reviewHead{border-bottom:1px solid var(--line);padding-bottom:17px;margin-bottom:3px}.reviewHead span{font-size:13px;color:var(--accent);font-weight:600}.reviewHead p{font-size:13px;color:#7e8a84;margin:5px 0 0}.resurfaceCard{padding:19px 0;border-bottom:1px solid var(--line)}.resurfaceCard>img{width:100%;height:175px;object-fit:cover;border-radius:11px;margin-bottom:13px}.cardTop{display:flex;justify-content:space-between;align-items:center;gap:8px;color:#8b958f;font-size:12px}.intentBadge,.stateBadge{display:inline-block;font-size:12px;padding:3px 8px;background:#eaf2ed;color:#496a59;border-radius:6px}.stateBadge{background:#f5f1e9;color:#8b724e}.resurfaceCard h3,.task h3{font-size:17px;font-weight:540;margin:9px 0 5px}.resurfaceCard p,.task p{font-size:13px;color:#7b8781;margin:0}.task{padding:18px 0;border-bottom:1px solid var(--line)}.taskActions{display:flex;gap:5px;margin-top:11px;flex-wrap:wrap}.taskActions button{font-size:13px;color:var(--accent);padding:5px 8px}\n.field{display:block;font-size:14px;margin:17px 0;color:#617169}.field input,.field select,.field textarea{display:block;width:100%;padding:10px 12px;border:1px solid #dce4df;border-radius:9px;margin-top:7px;font-size:15px;background:white;outline:0}.field textarea{min-height:90px}.field input:disabled,.field select:disabled,.field textarea:disabled{background:#f7f8f7;color:#5c6862;opacity:1}.media{width:100%;max-height:370px;object-fit:contain;display:block;margin:8px auto 17px;border-radius:11px;background:#f6f7f6}.summary{font-size:15px;line-height:1.85;padding:5px 0 12px;white-space:pre-wrap}.recognition{border-left:3px solid #a8c2b5;background:#f5f8f6;padding:14px 16px;margin:8px 0 19px;border-radius:0 9px 9px 0}.recognitionLabel{font-size:12px!important;color:#6f8378!important;margin:0 0 9px!important}.recognition strong{font-size:13px}.recognition p{font-size:14px;color:#66736d;margin:3px 0 10px}.source{white-space:pre-wrap;font-size:14px;color:#74827b;border-left:2px solid #d5e0d9;padding-left:14px;max-height:250px;overflow:auto;margin:16px 0}.linkrow{padding:11px;border:1px solid var(--line);border-radius:8px;margin:8px 0;display:flex;gap:10px;align-items:center}.linkrow a{word-break:break-all;font-size:14px;flex:1}.actions{display:flex;gap:10px;justify-content:flex-end;margin-top:21px;flex-wrap:wrap}.danger{color:var(--danger);background:#fcf2f1}.full{width:100%;margin-top:11px;border:1px solid #dce4df}.related{display:block;text-align:left;width:100%;font-size:14px;border-bottom:1px solid var(--line);padding:12px 0}.divider{height:1px;background:var(--line);margin:21px 0}.check{display:flex;gap:8px;align-items:flex-start;font-size:13px;margin-top:13px}.check input{margin-top:5px}.capabilityTitle{font-size:15px;font-weight:560;margin:0}.accountcard{padding:17px 0;border-bottom:1px solid var(--line)}.accountcard b{display:block;font-size:15px;font-weight:550}.accountcard p{font-size:14px;color:#7f8b85;word-break:break-word}.accountcard a{font-size:14px}.signin{display:block;text-align:center;text-decoration:none;padding:11px;border-radius:9px;background:var(--ink);color:white}.demoLabel{font-size:12px;color:#8c744e;background:#faf6ed;padding:9px 12px;border-radius:8px}#toast{display:none;position:fixed;bottom:25px;left:50%;transform:translateX(-50%);background:#273c32;color:white;border-radius:10px;padding:12px 20px;font-size:14px;z-index:9;max-width:90vw;box-shadow:0 12px 35px rgba(22,42,33,.2)}\n@media(max-width:880px){.workspace{width:calc(100% - 48px)}.featureGrid{grid-template-columns:1fr 1fr}.demoSpotlight{grid-template-columns:1fr}.demoSpotlight>img{height:270px;min-height:0}.demoSpotlight>div{padding:27px}}\n@media(max-width:650px){.rail{width:61px;padding:17px 3px}.logo{width:42px;height:42px}.rail nav{gap:11px;margin-top:27px}.rail nav button{width:54px}.navicon{font-size:20px}.rail nav button span:last-child{font-size:11px;margin-top:5px}main{margin-left:61px}header{height:70px;padding:0 20px}.headernote{max-width:135px;text-align:right}.wordmark span{display:none}.workspace{width:calc(100% - 32px);margin:26px auto 55px}.greeting{margin-bottom:25px}.greeting h1{font-size:31px}.greeting>p:last-child{font-size:14px}.composer{padding:14px}.modebar{overflow:auto}.modebar button{white-space:nowrap;font-size:13px}.metaGrid,.detailGrid,.recallGrid{grid-template-columns:1fr}.photoPrompt{display:block}.photoPrompt p{margin-top:3px}.composerfoot{gap:10px}.composerfoot>span{font-size:11px;line-height:1.45}.featureGrid{grid-template-columns:1fr}.featureGrid button{padding:14px}.demoSpotlight{margin-top:28px}.demoSpotlight>img{height:210px}.demoSpotlight>div{padding:22px}.demoSpotlight h2{font-size:21px}footer{padding:17px 20px}footer>span{display:none}.panel{padding:23px}.intentChips{gap:5px}.intentChips button{font-size:12px;padding:5px 8px}textarea{font-size:16px}.revisitLabel{max-width:none}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}.featureGrid button{transform:none!important}}\n"},"/app.js":{"type":"text/javascript; charset=utf-8","body":"const $=id=>document.getElementById(id);\nconst esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst intents=['想买','想学','想做','想试试','留作参考','只是好笑','重要凭证','只收藏','稍后看或试','学习','待行动'];\nconst visibleIntents=['想买','想学','想做','想试试','留作参考','只是好笑','重要凭证'];\nconst actionable=new Set(['想买','想学','想做','想试试','待行动','学习','稍后看或试']);\nconst icons={text:'≡',link:'↗',image:'▧',audio:'♪'};\nconst types={text:'文字',link:'链接',image:'图片',audio:'录音'};\nlet records=[],me=null,mode='text',selectedIntent='留作参考',attachment=null,attachmentURL=null,view='library',filter='全部',panelQuery='',recorder=null,stream=null,recordTimer=null,recordClock=null,saving=false;\n\nconst demo=[\n  {id:'demo-scenic',kind:'image',title:'大理洱海旁的观景位',text:'这个地方在大理洱海附近。我喜欢前景栏杆、湖面和远山的层次，下次傍晚去时想复刻相似构图。',summary:'画面由木质栏杆、平静湖面和远山组成，适合在日落前从观景台拍摄。',scene:'湖泊、山脉、树林与木质观景栏杆，画面有清楚的前中后景。',photoTips:'傍晚提前到达；使用横向构图；让栏杆保留在画面下方作为前景，人可站在栏杆转角附近。',topic:'旅行计划',intent:'想做',source:'小红书',clue:'大理 风景 湖边 同款照片',place:'大理洱海附近',photoPlan:'傍晚去，保留栏杆前景，拍湖面与远山的同款层次。',revisit:'下周',tags:['旅行','风景复刻'],status:'识别示例',createdAt:'2026-09-14',demo:true,demoImage:'/assets/demo-scenic-recreation.jpg'},\n  {id:'demo-song',kind:'image',title:'直播弹幕里推荐的几首歌',text:'当时在直播间看到弹幕推荐，先记下歌名，晚上戴耳机听。',summary:'保存的是直播弹幕中的歌单线索。',topic:'音乐清单',intent:'想试试',source:'直播',clue:'直播 弹幕 歌名 好听',place:'',photoPlan:'',revisit:'今晚',tags:['音乐','歌单'],status:'演示',createdAt:'2026-09-13',demo:true},\n  {id:'demo-japanese',kind:'image',title:'日语成对自他动词口诀',text:'最近在学日语，想把这组成对动词做成复习卡。',summary:'不是普通收藏，而是一条等待复习的学习记忆。',topic:'日语学习',intent:'想学',source:'小红书',clue:'日语 自他动词 口诀',place:'',photoPlan:'',revisit:'三天后',tags:['日语','自他动词'],status:'演示',createdAt:'2026-09-12',demo:true}\n];\n\nfunction notify(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(window.toasting);window.toasting=setTimeout(()=>$('toast').style.display='none',3600)}\nfunction show(id){if(!$(id).open)$(id).showModal()}\nasync function api(path,options={}){const res=await fetch('/api/'+path,options);let data;try{data=await res.json()}catch{throw new Error('服务暂时不可用，请稍后重试')}if(!res.ok)throw new Error(data.error||'操作失败，请重试');return data}\nasync function refresh(){const data=await api('memories');records=data.items;if($('panel').open)renderPanel()}\nasync function init(){try{me=await api('me');$('connection').textContent='私人空间 · 已登录';$('banner').textContent='第一版重点：保存目的、线索找回、行动闭环与再次出现。';await refresh()}catch(e){$('connection').textContent='空间尚未连接';$('banner').textContent=e.message}}\n\nfunction match(r,q){return !q||[r.title,r.text,r.extractedText,r.transcript,r.summary,r.topic,r.clue,r.source,r.place,r.photoPlan,r.scene,r.photoTips,...(r.tags||[]),...(r.links||[])].join(' ').toLowerCase().includes(q.trim().toLowerCase())}\nfunction row(r){const meta=[types[r.kind],r.intent,r.source,r.place,r.status].filter(Boolean).join(' · ');return `<div class=\"itemrow\"><span class=\"itemicon\">${icons[r.kind]||'≡'}</span><button class=\"rowopen\" data-open=\"${esc(r.id)}\"><strong>${esc(r.title)}</strong><p>${esc(meta)}</p></button>${r.deletedAt?`<button class=\"smallbtn\" data-restore=\"${r.id}\">恢复</button>`:`<button class=\"smallbtn\" data-delete=\"${r.id}\" aria-label=\"删除 ${esc(r.title)}\">删除</button>`}</div>`}\nfunction get(id){return records.find(r=>r.id===id)||demo.find(r=>r.id===id)}\nasync function patch(id,body){const r=await api('memories/'+id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(body)});records=records.map(x=>x.id===id?r:x);if($('panel').open)renderPanel();return r}\n\nfunction openPanel(v){view=v;filter='全部';panelQuery='';renderPanel();show('panel')}\nfunction renderPanel(){\n  const names={library:'全部记忆',recall:'凭印象找回',tasks:'等我去做',resurface:'再看一眼',trash:'回收站'};\n  $('paneltitle').textContent=names[view]||'记忆';\n  const active=records.filter(r=>!r.deletedAt);\n  if(view==='recall'){renderRecall(active);return}\n  if(view==='tasks'){\n    const tasks=active.filter(r=>r.reminder||actionable.has(r.intent));\n    $('panelbody').innerHTML='<p class=\"panelIntro\">只有你真正想买、想学、想做或想试的内容，才会来到这里。</p>'+(tasks.length?tasks.map(taskCard).join(''):'<div class=\"empty\"><strong>现在没有等待处理的内容</strong><p>保存时选择“想做”或“想学”，它就会出现在这里。</p></div>');return;\n  }\n  if(view==='resurface'){\n    const chosen=chooseResurface(active);\n    const list=chosen.length?chosen:demo;\n    $('panelbody').innerHTML='<div class=\"reviewHead\"><span>本次只看 3 条</span><p>不制造新的信息压力，只把值得处理的内容轻轻送回来。</p></div>'+list.slice(0,3).map(r=>resurfaceCard(r)).join('');return;\n  }\n  const list=records.filter(r=>view==='trash'?!!r.deletedAt:!r.deletedAt).filter(r=>match(r,panelQuery)&&(filter==='全部'||r.kind===filter));\n  $('panelbody').innerHTML=(view==='trash'?'<p class=\"panelIntro\">移入这里的资料已从找回和行动中隐藏，可以随时恢复。</p>':`<input class=\"panelsearch\" id=\"panelSearch\" aria-label=\"搜索资料库\" placeholder=\"输入关键词、地点或备注\" value=\"${esc(panelQuery)}\"><div class=\"filters\">${[['全部','全部'],['text','文字'],['image','图片'],['link','链接'],['audio','录音']].map(([v,n])=>`<button class=\"${filter===v?'active':''}\" data-filter=\"${v}\">${n}</button>`).join('')}</div>`)+`<div id=\"rows\">${list.length?list.map(row).join(''):'<div class=\"empty\"><strong>这里还很安静</strong><p>从首页保存第一段记忆，或换个关键词。</p></div>'}</div>`;\n  if($('panelSearch'))$('panelSearch').oninput=e=>{panelQuery=e.target.value;const found=records.filter(r=>!r.deletedAt&&match(r,panelQuery)&&(filter==='全部'||r.kind===filter));$('rows').innerHTML=found.map(row).join('')||'<p class=\"muted\">没有匹配内容</p>'};\n}\n\nfunction renderRecall(active){\n  $('panelbody').innerHTML=`<p class=\"panelIntro\">不用记得完整内容。把还记得的词、来源和大概时间告诉拾忆。</p><div class=\"recallBox\"><label>还记得哪个词？<input id=\"recallQuery\" placeholder=\"例如：歌名、栏杆、自他动词\"></label><div class=\"recallGrid\"><label>来源<select id=\"recallSource\"><option value=\"\">全部来源</option>${['小红书','微信','直播','游戏','网页','相册','其他'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>保存目的<select id=\"recallIntent\"><option value=\"\">全部目的</option>${visibleIntents.map(x=>`<option>${x}</option>`).join('')}</select></label><label>内容形式<select id=\"recallKind\"><option value=\"\">全部形式</option><option value=\"image\">图片</option><option value=\"text\">文字</option><option value=\"link\">链接</option><option value=\"audio\">录音</option></select></label><label>大概时间<select id=\"recallTime\"><option value=\"\">不限时间</option><option value=\"7\">最近一周</option><option value=\"30\">最近一个月</option><option value=\"365\">今年</option></select></label></div></div><div id=\"recallResult\"></div>`;\n  const update=()=>{const q=$('recallQuery').value,source=$('recallSource').value,intent=$('recallIntent').value,kind=$('recallKind').value,days=Number($('recallTime').value||0),cutoff=days?Date.now()-days*86400000:0;const found=active.filter(r=>match(r,q)&&(!source||r.source===source)&&(!intent||r.intent===intent)&&(!kind||r.kind===kind)&&(!cutoff||Date.parse(r.createdAt)>=cutoff));$('recallResult').innerHTML=found.length?`<p class=\"resultCount\">找到 ${found.length} 条可能的记忆</p>`+found.map(row).join(''):'<div class=\"empty\"><strong>换一条线索试试</strong><p>可以只选来源或大概时间，不必填写所有条件。</p></div>'};\n  ['recallQuery','recallSource','recallIntent','recallKind','recallTime'].forEach(id=>$(id).addEventListener(id==='recallQuery'?'input':'change',update));update();\n}\n\nfunction chooseResurface(active){return [...active].sort((a,b)=>{const ar=a.reminder&&a.reminder.status!=='已完成'?0:actionable.has(a.intent)?1:2;const br=b.reminder&&b.reminder.status!=='已完成'?0:actionable.has(b.intent)?1:2;return ar-br||Date.parse(a.createdAt)-Date.parse(b.createdAt)}).slice(0,3)}\nfunction taskCard(r){const reminder=r.reminder;return `<article class=\"task\"><div class=\"cardTop\"><span class=\"intentBadge\">${esc(r.intent||'待处理')}</span>${reminder?`<span class=\"stateBadge\">${esc(reminder.status)}</span>`:''}</div><h3>${esc(r.title)}</h3><p>${reminder?`${esc(reminder.when.replace('T',' '))} · ${esc(reminder.priority)}`:'还没有安排时间'}</p><div class=\"taskActions\"><button data-open=\"${r.id}\">查看</button>${reminder&&reminder.status!=='已完成'?`<button data-task=\"${r.id}\" data-status=\"已完成\">完成</button><button data-task=\"${r.id}\" data-status=\"delay\">延后一天</button>`:''}</div></article>`}\nfunction resurfaceCard(r){const image=r.demoImage?`<img src=\"${r.demoImage}\" alt=\"${esc(r.title)}\">`:'';return `<article class=\"resurfaceCard\">${image}<div class=\"cardTop\"><span class=\"intentBadge\">${esc(r.intent)}</span><span>${esc(r.source||types[r.kind])}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.summary||r.text||r.clue||'重新看一眼这段记忆。')}</p><div class=\"taskActions\"><button data-open=\"${r.id}\">打开</button>${r.demo?'<button data-demo-choice=\"later\">下周再看</button>':`<button data-resurface=\"keep\" data-id=\"${r.id}\">继续保留</button>${actionable.has(r.intent)?`<button data-resurface=\"done\" data-id=\"${r.id}\">已经完成</button>`:''}`}</div></article>`}\n\nfunction openDetail(id){\n  const r=get(id);if(!r)return;if(r.deletedAt){notify('请先从回收站恢复这份资料');return}\n  const related=(r.demo?demo:records).filter(x=>x.id!==r.id&&!x.deletedAt&&r.topic&&r.topic!=='未分类'&&x.topic===r.topic).slice(0,4);\n  const media=r.demoImage?`<img class=\"media\" src=\"${r.demoImage}\" alt=\"${esc(r.title)}\">`:r.hasFile?(r.kind==='image'?`<img class=\"media\" src=\"/api/memories/${r.id}/file\" alt=\"保存的原始图片\">`:`<audio controls src=\"/api/memories/${r.id}/file\"></audio>`):'';\n  const recognition=r.scene||r.photoTips?`<div class=\"recognition\"><p class=\"recognitionLabel\">${r.demo?'接入单张识图后的示例输出':'照片内容'}</p>${r.scene?`<strong>画面</strong><p>${esc(r.scene)}</p>`:''}${r.photoTips?`<strong>复刻建议</strong><p>${esc(r.photoTips)}</p>`:''}</div>`:'';\n  $('detailbody').innerHTML=`${r.demo?'<p class=\"demoLabel\">演示数据，不会混入你的真实资料</p>':''}${media}<div class=\"memoryMeta\"><span class=\"intentBadge\">${esc(r.intent||'留作参考')}</span>${r.source?`<span>${esc(r.source)}</span>`:''}${r.place?`<span>${esc(r.place)}</span>`:''}</div><label class=\"field\">内容标题<input id=\"editTitle\" maxlength=\"100\" value=\"${esc(r.title)}\" ${r.demo?'disabled':''}></label>${r.summary?`<div class=\"summary\">${esc(r.summary)}</div>`:''}${recognition}<label class=\"field\">原始内容 / 我的说明<textarea id=\"editText\" maxlength=\"20000\" ${r.demo?'disabled':''}>${esc(r.text)}</textarea></label>${(r.links||[]).map((link,i)=>`<div class=\"linkrow\"><a href=\"${esc(link)}\" target=\"_blank\" rel=\"noopener noreferrer\">${esc(link)} ↗</a><button class=\"smallbtn\" data-copy=\"${i}\" data-record=\"${r.id}\">复制</button></div>`).join('')}<div class=\"detailGrid\"><label class=\"field\">记忆线索<input id=\"editClue\" maxlength=\"120\" value=\"${esc(r.clue||'')}\" ${r.demo?'disabled':''}></label><label class=\"field\">来源<input id=\"editSource\" maxlength=\"60\" value=\"${esc(r.source||'')}\" ${r.demo?'disabled':''}></label><label class=\"field\">地点<input id=\"editPlace\" maxlength=\"100\" value=\"${esc(r.place||'')}\" ${r.demo?'disabled':''}></label><label class=\"field\">主题<input id=\"editTopic\" maxlength=\"60\" value=\"${esc(r.topic||'未分类')}\" ${r.demo?'disabled':''}></label></div><label class=\"field\">想怎么复刻 / 下一步<textarea id=\"editPhotoPlan\" maxlength=\"500\" ${r.demo?'disabled':''}>${esc(r.photoPlan||'')}</textarea></label><label class=\"field\">保存目的<select id=\"editIntent\" ${r.demo?'disabled':''}>${visibleIntents.map(m=>`<option ${r.intent===m?'selected':''}>${m}</option>`).join('')}</select></label>${related.length?'<div class=\"divider\"></div><p class=\"muted\">同一主题的记忆</p>'+related.map(x=>`<button class=\"related\" data-open=\"${x.id}\">${esc(x.title)} ↗</button>`).join(''):''}${!r.demo?`<div class=\"actions\"><button data-delete=\"${r.id}\" class=\"danger\">删除</button><button id=\"saveEdits\" class=\"primary\">保存修改</button></div>${r.kind==='image'||r.kind==='audio'?`<div class=\"divider\"></div><p class=\"capabilityTitle\">${r.kind==='image'?'可选：识别这张照片':'可选：转写这段录音'}</p><p class=\"muted\">${r.kind==='image'?'识别画面内容与构图，但地点仍以你填写的信息为准。此功能不是 AI 搜索。':'把录音转成可检索的文字。'}</p><label class=\"check\"><input type=\"checkbox\" id=\"aiConsent\">只将这一份资料发送给识别服务。</label><button id=\"analyze\" class=\"full\" ${!me?.aiEnabled?'disabled':''}>${r.kind==='image'?'识别照片内容':'转写录音'}${!me?.aiEnabled?' · 演示版暂未接入':''}</button>`:''}<button id=\"newReminder\" class=\"full\">安排跟进计划</button><p id=\"detailError\" class=\"error\" role=\"status\"></p>`:'<p class=\"muted\">真实保存时，你可以修改这些信息并安排回访。</p>'}`;\n  if(!r.demo){\n    $('saveEdits').onclick=async()=>{const b=$('saveEdits');b.disabled=true;try{await patch(id,{title:$('editTitle').value,text:$('editText').value,topic:$('editTopic').value,intent:$('editIntent').value,clue:$('editClue').value,source:$('editSource').value,place:$('editPlace').value,photoPlan:$('editPhotoPlan').value});notify('已保存');openDetail(id)}catch(e){$('detailError').textContent=e.message;b.disabled=false}};\n    if($('analyze'))$('analyze').onclick=async()=>{if(!$('aiConsent').checked){$('detailError').textContent='请先确认只发送这一份资料。';return}const b=$('analyze');b.disabled=true;b.textContent='正在处理…';try{await api('memories/'+id+'/analyze',{method:'POST'});await refresh();openDetail(id);notify('识别完成，请核对结果')}catch(e){$('detailError').textContent=e.message;b.disabled=false;b.textContent='重试'}};\n    $('newReminder').onclick=()=>reminder(r);\n  }\n  show('detail');\n}\n\nfunction reminder(r){const now=new Date(Date.now()+86400000);now.setMinutes(now.getMinutes()-now.getTimezoneOffset());$('detailbody').innerHTML=`<h3>${esc(r.title)}</h3><form id=\"reminderform\"><label class=\"field\">重要程度<select id=\"priority\"><option>普通</option><option>重要</option><option>优先处理</option></select></label><label class=\"field\">计划时间<input required id=\"when\" type=\"datetime-local\" value=\"${now.toISOString().slice(0,16)}\"></label><label class=\"field\">跟进频率<select id=\"frequency\"><option>仅一次</option><option>每天</option><option>每周</option></select></label><p class=\"panelIntro\">计划会保存在“等我去做”。演示版暂不发送系统通知。</p><button class=\"primary full\">保存计划</button><p id=\"reminderError\" class=\"error\"></p></form>`;$('reminderform').onsubmit=async e=>{e.preventDefault();if(new Date($('when').value)<=new Date()){$('reminderError').textContent='请选择未来时间';return}try{await patch(r.id,{reminder:{when:$('when').value,priority:$('priority').value,frequency:$('frequency').value,status:'进行中'}});$('detail').close();openPanel('tasks');notify('计划已保存')}catch(err){$('reminderError').textContent=err.message}}}\nfunction deleteRecord(id){const r=get(id);if(!r||r.demo)return;show('confirm');$('confirmDelete').onclick=async()=>{$('confirmDelete').disabled=true;try{await patch(id,{deleted:true});$('confirm').close();$('detail').close();notify('已移到回收站，可随时恢复')}catch(e){notify(e.message)}finally{$('confirmDelete').disabled=false}}}\n\nfunction switchMode(next){if(recorder?.state==='recording'){notify('先停止录音，再切换输入方式');return}mode=next;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===mode));$('attachmentArea').hidden=mode==='text';$('recordArea').hidden=mode!=='audio';$('photoFields').hidden=mode!=='image';$('file').accept=mode==='image'?'image/png,image/jpeg,image/webp':'audio/*';$('filelabel').textContent=mode==='image'?'选择图片，或拖到这里':'选择已有录音，也可以直接录制';$('thought').placeholder=mode==='text'?'随手写点什么，也可以粘贴链接…':mode==='image'?'说明这张图是什么、在哪里看到、为什么想留下…':'给这段声音补充一句说明…';$('savehint').textContent=mode==='image'?'先记录你知道的地点和目的；识图可以以后再开。':'保存内容，也保存你当时的目的。';clearAttachment()}\nfunction clearAttachment(){attachment=null;if(attachmentURL)URL.revokeObjectURL(attachmentURL);attachmentURL=null;$('attachmentPreview').innerHTML='';$('file').value=''}\nfunction setAttachment(file){if(file.size>10*1024*1024){notify('文件需小于 10 MB');return}const image=['image/png','image/jpeg','image/webp'].includes(file.type);const audio=/^(audio\\/|video\\/webm)/.test(file.type);if(!image&&!audio){notify('请选择 PNG、JPG、WebP 图片或音频');return}if(recorder?.state==='recording'){notify('请先停止录音');return}if(mode!==(image?'image':'audio'))switchMode(image?'image':'audio');clearAttachment();attachment=file;attachmentURL=URL.createObjectURL(file);$('attachmentPreview').innerHTML=(image?`<img src=\"${attachmentURL}\" alt=\"待保存图片\">`:`<audio controls src=\"${attachmentURL}\"></audio>`)+`<button id=\"removeFile\" class=\"smallbtn\">移除附件</button>`;$('removeFile').onclick=clearAttachment}\n\nfunction revisitDate(choice){const d=new Date();if(choice==='今晚')d.setHours(20,0,0,0);if(choice==='三天后')d.setDate(d.getDate()+3);if(choice==='下周')d.setDate(d.getDate()+7);if(choice==='一个月后')d.setMonth(d.getMonth()+1);if(d<=new Date())d.setDate(d.getDate()+1);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)}\nasync function save(){if(saving)return;if(recorder?.state==='recording'){notify('请先停止录音并试听');return}const text=$('thought').value.trim();if(!text&&!attachment){notify('先写点内容，或添加图片、录音');return}if(!me){openAccount();return}saving=true;$('save').disabled=true;$('save').textContent='保存中…';const form=new FormData(),revisit=$('revisit').value;form.set('text',text);form.set('intent',selectedIntent);form.set('clue',$('clue').value.trim());form.set('source',$('source').value);form.set('place',$('place').value.trim());form.set('photoPlan',$('photoPlan').value.trim());form.set('revisit',revisit);if(revisit!=='不用提醒')form.set('revisitWhen',revisitDate(revisit));if(attachment)form.set('file',attachment);try{const r=await api('memories',{method:'POST',body:form});$('thought').value='';$('clue').value='';$('place').value='';$('photoPlan').value='';$('source').value='';$('revisit').value='不用提醒';clearAttachment();records.unshift(r);notify('已收好：内容、目的和线索都已保存');openDetail(r.id)}catch(e){notify(e.message)}finally{saving=false;$('save').disabled=false;$('save').textContent='收好'}}\n\nasync function record(){if(recorder?.state==='recording'){recorder.stop();return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){notify('当前浏览器不支持录音，可以上传已有音频文件');return}try{stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:{});const parts=[];let seconds=0;recorder.ondataavailable=e=>{if(e.data.size)parts.push(e.data)};recorder.onstop=()=>{clearTimeout(recordTimer);clearInterval(recordClock);stream.getTracks().forEach(t=>t.stop());const type=recorder.mimeType;const file=new File(parts,'录音.'+(type.includes('mp4')?'m4a':'webm'),{type});recorder=null;$('record').textContent='● 重新录音';$('recordState').textContent='录音已停止，可试听后保存';setAttachment(file)};recorder.start();$('record').textContent='■ 停止录音';$('recordState').textContent='正在录音 0:00';recordClock=setInterval(()=>{seconds++;$('recordState').textContent=`正在录音 ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`},1000);recordTimer=setTimeout(()=>{if(recorder?.state==='recording')recorder.stop()},120000)}catch{stream?.getTracks().forEach(t=>t.stop());notify('未获得麦克风权限，可以上传已有录音')}}\n\nfunction openAccount(){$('accountbody').innerHTML=`<div class=\"accountcard\"><b>${me?'已登录 · 私人空间':'登录 / 首次使用'}</b><p>${me?esc(me.email):'首次通过 ChatGPT 登录后，即可使用账号空间。'}</p>${me?'<a href=\"/signout-with-chatgpt?return_to=%2F\" target=\"_top\">退出登录</a>':'<a class=\"signin\" href=\"/signin-with-chatgpt?return_to=%2F\" target=\"_top\">使用 ChatGPT 登录</a>'}<p>文字、图片与行动计划按账号隔离保存。</p></div><div class=\"accountcard\"><b>关键词找回 · 不使用 AI</b><p>根据你填写的记忆词、来源、地点、目的与时间组合筛选，不产生模型费用。</p></div><div class=\"accountcard\"><b>单张照片识别 · ${me?.aiEnabled?'可以使用':'演示版暂未接入'}</b><p>可以描述画面中的景物、文字和构图，并给出复刻拍摄建议；无法只凭普通风景照保证认出准确地点，因此地点以你填写的内容为准。</p><p>它与 AI 搜索相互独立，只在你打开某一张照片并主动确认后处理这一张。</p></div><div class=\"accountcard\"><b>数据可带走</b><p>删除先进入回收站。你也可以导出全部文字信息与链接。</p><button id=\"export\" ${!me?'disabled':''}>导出文字资料</button></div>`;if($('export'))$('export').onclick=()=>{const blob=new Blob([JSON.stringify(records,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='拾忆-文字资料.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('文字资料已导出')};show('accountDialog')}\n\ndocument.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.view)openPanel(b.dataset.view);if(b.dataset.close)$(b.dataset.close).close();if(b.dataset.open)openDetail(b.dataset.open);if(b.dataset.delete)deleteRecord(b.dataset.delete);if(b.dataset.restore){await patch(b.dataset.restore,{deleted:false});notify('已恢复资料')}if(b.dataset.mode)switchMode(b.dataset.mode);if(b.dataset.intent){selectedIntent=b.dataset.intent;document.querySelectorAll('[data-intent]').forEach(x=>x.classList.toggle('active',x.dataset.intent===selectedIntent))}if(b.dataset.filter){filter=b.dataset.filter;renderPanel()}if('copy' in b.dataset){await navigator.clipboard.writeText(get(b.dataset.record).links[Number(b.dataset.copy)]);notify('链接已复制')}if(b.dataset.task){const r=get(b.dataset.task);let rem={...r.reminder};if(b.dataset.status==='delay'){const d=new Date(rem.when);d.setDate(d.getDate()+1);d.setMinutes(d.getMinutes()-d.getTimezoneOffset());rem.when=d.toISOString().slice(0,16)}else rem.status=b.dataset.status;await patch(r.id,{reminder:rem});notify('行动状态已更新')}if(b.dataset.resurface==='done'){const r=get(b.dataset.id);await patch(r.id,{lifeStatus:'已完成',reminder:r.reminder?{...r.reminder,status:'已完成'}:null});notify('太好了，已经完成')}if(b.dataset.resurface==='keep')notify('继续为你保留');if(b.dataset.demoChoice)notify('演示：它会在下周再次出现');if('focusCapture' in b.dataset){document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('composer').scrollIntoView({behavior:'smooth',block:'center'});$('thought').focus()}}catch(err){notify(err.message)}});\n\n$('save').onclick=save;$('file').onchange=e=>{if(e.target.files[0])setAttachment(e.target.files[0])};$('filepick').ondragover=e=>e.preventDefault();$('filepick').ondrop=e=>{e.preventDefault();if(e.dataTransfer.files[0])setAttachment(e.dataTransfer.files[0])};$('thought').onpaste=e=>{if(e.clipboardData.files.length){e.preventDefault();setAttachment(e.clipboardData.files[0])}};$('record').onclick=record;$('account').onclick=openAccount;$('aboutPhoto').onclick=openAccount;$('openScenicDemo').onclick=()=>openDetail('demo-scenic');$('home').onclick=()=>{document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('composer').scrollIntoView({behavior:'smooth',block:'start'})};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPanel('recall');setTimeout(()=>$('recallQuery')?.focus(),0)}});window.addEventListener('pagehide',()=>{stream?.getTracks().forEach(t=>t.stop());clearTimeout(recordTimer);clearInterval(recordClock)});init();\n\nif(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'find_saved_memory',description:'Find saved memories using exact keywords and user-provided context such as source, place, intent, and notes. Does not call AI.',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(typeof input?.query!=='string')throw new Error('query must be a string');openPanel('recall');setTimeout(()=>{if($('recallQuery')){$('recallQuery').value=input.query;$('recallQuery').dispatchEvent(new Event('input'))}},0);return{items:records.filter(r=>!r.deletedAt&&match(r,input.query)).map(r=>({id:r.id,title:r.title}))}}})).catch(()=>{})}catch{}}\n"},"/assets/demo-scenic-recreation.jpg":{"type":"image/jpeg","encoding":"base64","body":""}};
